const LIMITES = {
  'NUEVO': 24,
  'CONTACTADO': 48,
  'EN NEGOCIACION': 72
};

const HORAS_ADVERTENCIA_NUEVO = 2;

const resultados = [];

for (const item of $input.all()) {
  const lead = item.json;

  if (!lead || typeof lead !== 'object') continue;

  const status = (lead.status || '').toUpperCase().trim();
  const limitHoras = LIMITES[status];

  if (!limitHoras) continue;

  const fechaStatus = new Date(lead.fecha_ultimo_status);
  const ahora = new Date();
  const diffMs = ahora.getTime() - fechaStatus.getTime();
  const horasSinCambio = Math.floor(diffMs / (1000 * 60 * 60));
  const horasRestantes = limitHoras - horasSinCambio;

  let tipoAlerta = null;

  if (status === 'NUEVO') {
    if (horasSinCambio >= limitHoras) {
      tipoAlerta = 'VENCIDO';
    } else if (horasRestantes <= HORAS_ADVERTENCIA_NUEVO) {
      tipoAlerta = 'ADVERTENCIA';
    }
  } else {
    // CONTACTADO y EN NEGOCIACION: solo alerta cuando vence
    if (horasSinCambio >= limitHoras) {
      tipoAlerta = 'VENCIDO';
    }
  }

  if (!tipoAlerta) continue;

  resultados.push({
    json: {
      ...lead,
      tipoAlerta,
      horasSinCambio,
      horasRestantes: horasRestantes > 0 ? horasRestantes : 0,
      limitHoras,
      updatedAtFormateado: fechaStatus.toLocaleString('es-VE', {
        timeZone: 'America/Caracas'
      })
    }
  });
}

return resultados;

const allItems = $input.all();
const admin = $('MySQL - Obtener ADmin Leads').first().json;
const resultados = [];

function formatearTiempo(horas) {
  if (horas < 24) {
    return horas + ' hora' + (horas !== 1 ? 's' : '');
  }
  const dias = Math.floor(horas / 24);
  const resto = horas % 24;
  if (resto === 0) {
    return dias + ' día' + (dias !== 1 ? 's' : '');
  }
  return dias + ' día' + (dias !== 1 ? 's' : '') + ' y ' + resto + ' hora' + (resto !== 1 ? 's' : '');
}

for (let i = 0; i < allItems.length; i++) {
  const d = allItems[i].json;

  const seller = {
