      + '</div>'
    : '<div style="background:#F8D7DA;border-left:4px solid #E74C3C;padding:16px;margin-bottom:16px;border-radius:4px;">'
      + '<p style="margin:0;color:#721C24;font-weight:bold;">🔴 LEAD VENCIDO</p>'
