    + '<p>Hola <strong>' + seller.seller_name + '</strong>,</p>'
    + '<p>El siguiente lead requiere tu atención inmediata:</p>'
    + alertaBanner
    + '<table style="width:100%;border-collapse:collapse;margin:16px 0;">'
    + '<tr style="background:#f5f5f5;">'
    + '<td style="padding:10px;font-weight:bold;border:1px solid #ddd;width:40%;">Cliente</td>'
    + '<td style="padding:10px;border:1px solid #ddd;">' + clienteNombre + '</td>'
    + '</tr>'
    + '<tr>'
    + '<td style="padding:10px;font-weight:bold;border:1px solid #ddd;">Status actual</td>'
    + '<td style="padding:10px;border:1px solid #ddd;"><strong style="color:#E74C3C;">' + lead.status + '</strong></td>'
    + '</tr>'
    + '<tr style="background:#f5f5f5;">'
    + '<td style="padding:10px;font-weight:bold;border:1px solid #ddd;">Tiempo en status</td>'
    + '<td style="padding:10px;border:1px solid #ddd;">' + tiempoEnStatus + '</td>'
    + '</tr>'
    + '<tr>'
    + '<td style="padding:10px;font-weight:bold;border:1px solid #ddd;">En status desde</td>'
    + '<td style="padding:10px;border:1px solid #ddd;">' + lead.updatedAtFormateado + '</td>'
    + '</tr>'
    + '</table>'
    + '<hr style="border:1px solid #eee;margin:20px 0;">'
    + '<p style="font-size:12px;color:#999;margin:0;">SUPRICOM · Tu mayorista de confianza 🦁</p>'
    + '</div></div>';

  let adminEmailHTML = null;
  let adminEmailSubject = null;

  if (esNuevoVencido) {
    adminEmailSubject = '🔁 Reasignación requerida: ' + clienteNombre + ' lleva ' + formatearTiempo(lead.horasSinCambio) + ' en NUEVO';
    adminEmailHTML = '<div style="font-family:Arial,sans-serif;max-width:600px;margin:0 auto;">'
      + '<div style="background:#721C24;color:white;padding:20px;border-radius:8px 8px 0 0;">'
      + '<h2 style="margin:0;">🔁 Lead pendiente de reasignación - SUPRICOM</h2>'
      + '</div>'
      + '<div style="border:1px solid #ddd;padding:24px;border-radius:0 0 8px 8px;">'
      + '<p>Hola <strong>' + admin.admin_name + '</strong>,</p>'
      + '<p>El siguiente lead en status <strong>NUEVO</strong> ha vencido sin ser contactado y requiere reasignación:</p>'
      + '<table style="width:100%;border-collapse:collapse;margin:16px 0;">'
      + '<tr style="background:#f5f5f5;">'
      + '<td style="padding:10px;font-weight:bold;border:1px solid #ddd;width:40%;">Cliente</td>'
      + '<td style="padding:10px;border:1px solid #ddd;">' + clienteNombre + '</td>'
      + '</tr>'
      + '<tr>'
      + '<td style="padding:10px;font-weight:bold;border:1px solid #ddd;">Vendedor actual</td>'
      + '<td style="padding:10px;border:1px solid #ddd;">' + seller.seller_name + '</td>'
      + '</tr>'
      + '<tr style="background:#f5f5f5;">'
      + '<td style="padding:10px;font-weight:bold;border:1px solid #ddd;">Tiempo en NUEVO</td>'
      + '<td style="padding:10px;border:1px solid #ddd;"><strong style="color:#E74C3C;">' + formatearTiempo(lead.horasSinCambio) + '</strong>'
      + ' <span style="color:#888;font-size:12px;">(límite: ' + formatearTiempo(lead.limitHoras) + ')</span></td>'
      + '</tr>'
      + '<tr>'
      + '<td style="padding:10px;font-weight:bold;border:1px solid #ddd;">En status desde</td>'
      + '<td style="padding:10px;border:1px solid #ddd;">' + lead.updatedAtFormateado + '</td>'
      + '</tr>'
      + '</table>'
      + '<div style="background:#F8D7DA;border-left:4px solid #E74C3C;padding:16px;border-radius:4px;">'
      + '<p style="margin:0;color:#721C24;font-weight:bold;">Por favor reasigna este lead a otro vendedor disponible.</p>'
      + '</div>'
      + '<hr style="border:1px solid #eee;margin:20px 0;">'
      + '<p style="font-size:12px;color:#999;margin:0;">SUPRICOM · Tu mayorista de confianza 🦁</p>'
      + '</div></div>';
  }

  let waParam1 = '', waParam2 = '', waParam3 = '', waParam4 = '';

  if (lead.status === 'NUEVO' && lead.tipoAlerta === 'ADVERTENCIA') {
    waParam1 = seller.seller_name;
    waParam2 = clienteNombre;
    waParam3 = formatearTiempo(lead.horasSinCambio);
    waParam4 = formatearTiempo(lead.horasRestantes);
  } else if (lead.status === 'NUEVO' && lead.tipoAlerta === 'VENCIDO') {
    waParam1 = seller.seller_name;
    waParam2 = clienteNombre;
    waParam3 = formatearTiempo(lead.horasSinCambio);
  } else if (lead.tipoAlerta === 'VENCIDO') {
    waParam1 = seller.seller_name;
    waParam2 = clienteNombre;
    waParam3 = formatearTiempo(lead.horasSinCambio);
