}

return resultados;

const allSellers = $input.all();
const allLeads = $('IF - Necesita Alerta').all();

const resultados = [];

for (let i = 0; i < allSellers.length; i++) {
  const seller = allSellers[i].json;
  const lead = allLeads[i]?.json;

  if (!seller || !lead) continue;

  resultados.push({
    json: {
      ...seller,
      ...lead,
      seller_name_real: seller.seller_name,
      seller_email_real: seller.seller_email,
      seller_whatsapp_real: seller.seller_whatsapp
    }
  });
}

return resultados;
